    const result = { ok: true, status: response.status, order: body.order, replayed: body.replayed === true };
    results.push(result);
    return result;
  } catch (error) {
    const result = { ok: false, status: null, error: error.message };
    results.push(result);
    return result;
  }
}

async function render() {
  $('#trace').replaceChildren();
  for (const [index, result] of results.entries()) {
    const line = document.createElement('div');
    line.className = 'trace-row';
    line.textContent = result.ok
      ? `응답 ${index + 1} · ${result.status} · ${result.order.id} · ${result.replayed ? '기존 주문 결과 재사용' : '새 주문 생성'}`
      : `응답 ${index + 1} · 실패${result.status ? ` · HTTP ${result.status}` : ''} · ${result.error}`;
    $('#trace').append(line);
  }
  const response = await fetch(`/api/orders?checkoutId=${encodeURIComponent(checkoutId)}`);
  if (!response.ok) throw new Error(`주문 목록 조회 실패: HTTP ${response.status}`);
  const { items, total } = await response.json();
  setCount('#order-count', total, '건');
  $('#orders').replaceChildren();
  for (const order of items) {
    const row = document.createElement('div');
    row.className = 'order-row';
    const id = document.createElement('strong');
    id.textContent = order.id;
    const name = document.createElement('span');
    name.textContent = order.productName;
    const amount = document.createElement('span');
    amount.textContent = money(order.amount);
    row.append(id, name, amount);
    $('#orders').append(row);
  }
  const duplicate = total > expectedOrders;
  const mismatch = total !== expectedOrders;
  $('#result-banner').dataset.state = duplicate ? 'duplicate' : 'ok';
  $('#result-title').textContent = duplicate
    ? '의도한 주문보다 더 많이 생성되었습니다'
    : mismatch ? '의도한 주문 수와 다릅니다' : '의도한 주문 수와 일치합니다';
  $('#result-detail').textContent = `의도한 주문 ${expectedOrders}건 / 실제 생성 ${total}건`;
}

async function submit(count, newOrder = false) {
  if (submitting) return;
  submitting = true;
  for (const button of document.querySelectorAll('button')) button.disabled = true;
  if (newOrder) {
    requestKey = crypto.randomUUID();
  }
  if (!expectedKeys.has(requestKey)) {
    expectedKeys.add(requestKey);
    expectedOrders += 1;
  }
  $('#feedback').textContent = '서버 응답을 기다리는 중입니다…';
  delete $('#feedback').dataset.error;
  try {
    const outcomes = await Promise.all(Array.from({ length: count }, () => send(requestKey)));
    const failures = outcomes.filter((outcome) => !outcome.ok).length;
    await render();
    const replays = outcomes.filter((outcome) => outcome.ok && outcome.replayed).length;
    const created = outcomes.filter((outcome) => outcome.ok && !outcome.replayed).length;
    $('#feedback').textContent = failures
      ? `${outcomes.length}개 요청 중 ${failures}개가 실패했습니다. 각 응답과 현재 주문 목록을 확인하세요. 실제 결제는 실행하지 않았습니다.`
      : `새 주문 ${created}건 · 기존 결과 재사용 ${replays}건. 실제 결제는 실행하지 않았습니다.`;
    if (failures) $('#feedback').dataset.error = 'true';
  } catch (error) {
    $('#feedback').textContent = error.message;
    $('#feedback').dataset.error = 'true';
  } finally {
    submitting = false;
    for (const button of document.querySelectorAll('button')) button.disabled = false;
  }
}

$('#send-once').addEventListener('click', () => submit(1));
$('#send-twice').addEventListener('click', () => submit(2));
$('#new-order').addEventListener('click', () => submit(1, true));

